    const ref = m <= 90 ? m : m <= 180 ? 180 - m : m <= 270 ? m - 180 : 360 - m;
    const S = { 0: '0', 30: '1/2', 45: '√2/2', 60: '√3/2', 90: '1' };
    const C = { 0: '1', 30: '√3/2', 45: '√2/2', 60: '1/2', 90: '0' };
    const T = { 0: '0', 30: '√3/3', 45: '1', 60: '√3', 90: null };
